import console from 'node:console'
import { copyFile, mkdir, readFile, writeFile } from 'node:fs/promises'
import { resolve } from 'node:path'
import { root } from './font-inputs.mjs'

// Preserve upstream unicode ranges; remove legacy WOFF payloads and unused scripts.
const families = [
  ['inter', ['400', '500', '600']],
  ['ibm-plex-mono', ['400', '500']],
  ['cormorant-garamond', ['500']],
  ['source-serif-4', ['400', '600', '800', '400-italic']],
  ['noto-serif-sc', ['400', '600', '900']],
]
const blocks = [
  '/* Generated by pnpm fonts:css. All faces are local WOFF2 with font-display: swap. */',
]
await mkdir(resolve(root, 'public/fonts'), { recursive: true })
for (const [family, variants] of families) {
  const packagePath = resolve(root, 'node_modules/@fontsource', family)
  await copyFile(
    resolve(packagePath, 'LICENSE'),
    resolve(root, `public/fonts/${family}-OFL.txt`),
  )
  for (const variant of variants) {
    const source = await readFile(
      resolve(packagePath, `${variant}.css`),
      'utf8',
    )
    for (const match of source.matchAll(/@font-face\s*\{[^}]+\}/g)) {
      const block = match[0]
      const file = block.match(/url\(\.\/files\/([^)]*\.woff2)\)/)?.[1]
      if (!file) throw new Error(`Missing WOFF2 face: ${family}/${variant}`)
      if (
        family !== 'noto-serif-sc' &&
        !file.includes('-latin-') &&
        !file.includes('-latin-ext-')
      )
        continue
      blocks.push(
        block.replace(
          /src:[^;]+;/,
          `src: url('@fontsource/${family}/files/${file}') format('woff2');`,
        ),
      )
    }
  }
}
blocks.push(`/* A real content subset. Input sources and checksum: src/assets/fonts/wenkai-manifest.json. */
@font-face {
  font-family: 'LXGW WenKai';
  font-style: normal;
  font-display: swap;
  font-weight: 400;
  src: url('../assets/fonts/lxgw-wenkai-content.woff2') format('woff2');
}`)
await writeFile(
  resolve(root, 'src/styles/fonts.css'),
  `${blocks.join('\n\n')}\n`,
)
console.log(
  `Generated ${blocks.length - 1} local font faces and copied five OFL licenses`,
)
